package com.exe201.rrms.service;
import com.exe201.rrms.entity.*; import com.exe201.rrms.repository.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import java.time.*;
@Service public class ListingMaintenanceService { private final ListingRepository repo; private final NotificationService n; public ListingMaintenanceService(ListingRepository r,NotificationService n){repo=r;this.n=n;} @Scheduled(cron="0 0 */6 * * *") public void run(){LocalDateTime now=LocalDateTime.now();for(Listing l:repo.findByStatus("ACTIVE")){boolean vip=l.getPackageUntil()!=null&&l.getPackageUntil().isAfter(now); if(l.getPackageUntil()!=null&&l.getPackageUntil().isBefore(now)){l.setPackageTier("FREE");l.setPackagePriority(0);l.setPackageUntil(null); if(l.getFreshnessDueAt()==null||l.getFreshnessDueAt().isBefore(now))l.setFreshnessDueAt(now.plusDays(15));repo.save(l);n.send(l.getLandlordId(),"VIP_EXPIRED","Gói VIP của tin #"+l.getId()+" đã hết hạn.","LISTING",l.getId());} if(!vip&&l.getFreshnessDueAt()!=null&&l.getFreshnessDueAt().isBefore(now)){ if(l.getFreshnessDueAt().plusDays(3).isBefore(now)){l.setStatus("HIDDEN_STALE");repo.save(l);n.send(l.getLandlordId(),"LISTING_HIDDEN","Tin #"+l.getId()+" đã được ẩn do chưa xác nhận tình trạng phòng.","LISTING",l.getId());} else n.send(l.getLandlordId(),"FRESHNESS_REMINDER","Vui lòng xác nhận lại tình trạng tin #"+l.getId()+" trong 3 ngày.","LISTING",l.getId()); } }} }
